<?php
declare(strict_types=1);require __DIR__.'/../src/Qipu.php';
$root=sys_get_temp_dir().'/qipu-recovery-'.bin2hex(random_bytes(6));mkdir($root,0700);$q=new QipuDemo($root);function check($x,$m){if(!$x)throw new RuntimeException($m);echo "PASS $m\n";}
try{$q->locked(fn()=>$q->pending());$r=QipuDemo::frame(QipuDemo::REQUEST,QipuDemo::json(['op'=>'sale','sku'=>'SKU-A','qty'=>5]));$q->locked(fn()=>$q->submit('A',0,0,$r));try{$q->locked(fn()=>$q->decide('A',0,1,true));throw new LogicException('Expected interruption');}catch(RuntimeException $e){if($e->getMessage()!=='Simulated interruption after C')throw $e;} $p=new Storage($root);$end=$p->head('C')['end'];check($p->head('RA')['end']===0,'C durable antes de R; caída simulada');unset($q);$q=new QipuDemo($root);$z=$q->locked(fn()=>$q->pending());check($z['canonical'][0]['vectors'][2]['values']->{'0'}===15&&$z['nodes']['A']['responses']===1,'Recuperación autónoma de respuesta por procedencia');check($p->head('C')['end']===$end&&$p->read('RA',0,1)['bytes']==="\x80",'Sin duplicación canónica; R completado');check($q->locked(fn()=>$q->decide('A',0,1))['status']==='replayed','Reintento posterior idempotente');echo "4/4 recuperación\n";}finally{foreach(glob($root.'/*') as $f)unlink($f);rmdir($root);}
